[ExtensionOf(classStr(MarkupTransInsert))]
final class AVAMarkupTransInsert_Extension
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_accountCode">_accountCode</param>
/// <param name = "_itemCode">_itemCode</param>
/// <param name = "_dlvModeCode">_dlvModeCode</param>
protected void insertForCodes(TableGroupAll _accountCode, TableGroupAll _itemCode, TableGroupAll _dlvModeCode)
{
    next insertForCodes(_accountCode,_itemCode,_dlvModeCode);

    if (_accountCode == TableGroupAll::GroupId)
    {

        MarkupAutoTable markupAutoTable = MarkupAutoTable::KCS_BOSfindTOSMarkup(parameters.ModuleCategory,
                                                                                                parameters.ModuleType,
                                                                                                parameters.Account,
                                                                                                _itemCode,
                                                                                                itemRelation,
                                                                                                ReturnCodeType::None,
                                                                                                '',
                                                                                                false,
                                                                                                _dlvModeCode,
                                                                                                dlvModeRelation);


        if (markupAutoTable)
        {
            this.insertForMarkupAutoTable(markupAutoTable);
        }
    }
}
